{
  "findings": [
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe hides an early termination fee of 50 percent of remaining monthly payments if you cancel in the first year.",
      "stance": "risk",
      "quote": "the early termination fee (ETF) ... can be as much as 50 percent of the remaining monthly payments if you cancel within the first year[[2]](#cite-ftc-2)"
    },
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe buries the early termination fee in fine print or behind small icons.",
      "stance": "risk",
      "quote": "Adobe's failure to disclose these terms clearly is central to FTC's allegations[[2]](#cite-ftc-2)"
    },
    {
      "ref": "[2]",
      "area": "money",
      "claim": "A parent reports that Adobe makes cancelling subscriptions unnecessarily complicated.",
      "stance": "risk",
      "quote": "Adobe's cancellation process as intentionally complex, designed to deter consumers from canceling their subscriptions[[2]](#cite-ftc-2)"
    },
    {
      "ref": "[7]",
      "area": "money",
      "claim": "A parent reports that the settlement requires Adobe to give subscribers easy ways to cancel and to clearly disclose any early termination fee before enrollment.",
      "stance": "mitigation",
      "quote": "The Justice Department says the order requires Adobe to give subscribers easy ways to cancel. Adobe must also clearly disclose any ETF and how it is calculated before enrolling customers[[7]](#doj-adobe-rosca-settlement)"
    },
    {
      "ref": "[7]",
      "area": "money",
      "claim": "A parent reports that the settlement includes a $75 million civil penalty and $75 million in free services for customers.",
      "stance": "risk",
      "quote": "Adobe agreed to pay $75 million in civil penalties and offer customers $75 million in free services, a total of $150 million[[7]](#doj-adobe-rosca-settlement)"
    },
    {
      "ref": "[8]",
      "area": "money",
      "claim": "A parent reports that Adobe denies wrongdoing and disagrees with the government's claims.",
      "stance": "neutral",
      "quote": "Adobe said it disagrees with the government's claims and denies any wrongdoing[[8]](#reuters-adobe-settlement-2026)"
    },
    {
      "ref": "[1]",
      "area": "content",
      "claim": "A parent reports that the FTC complaint alleges Adobe hid early termination fees and made cancellation hard, violating ROSCA.",
      "stance": "risk",
      "quote": "The complaint accuses Adobe of deceptive practices related to its subscription plans, specifically failing to disclose early termination fees (ETFs) and making the cancellation process unnecessarily complicated[[1]](#cite-ftc-1)"
    },
    {
      "ref": "[1]",
      "area": "content",
      "claim": "A parent reports that Adobe's cancellation process forces users to navigate multiple pages and complete mandatory feedback that displays the ETF.",
      "stance": "risk",
      "quote": "When attempting to cancel, consumers must navigate through multiple pages on Adobe's website, starting with locating the account management page, clicking on \"Manage Plan,\" and then selecting \"Cancel Your Plan.\"[[1]](#cite-ftc-1)"
    },
    {
      "ref": "[1]",
      "area": "content",
      "claim": "A parent reports that Adobe customer service drops calls, disconnects chats, and transfers customers, adding difficulty to cancellation.",
      "stance": "risk",
      "quote": "Consumers also reported continued billing despite believing they had canceled their subscriptions, further exacerbating their frustration[[1]](#cite-ftc-1)"
    },
    {
      "ref": "[1]",
      "area": "content",
      "claim": "A parent reports that Adobe executives Maninder Sawhney and David Wadhwani were aware of and continued the unlawful practices.",
      "stance": "risk",
      "quote": "The complaint also targets Adobe executives Sawhney, Senior Vice President of Digital Go To Market & Sales, and Wadhwani, President of Digital Media Business, accusing them of being aware of and continuing the unlawful practices[[1]](#cite-ftc-1)"
    },
    {
      "ref": "[3]",
      "area": "money",
      "claim": "A parent reports that Adobe's subscription terms require a year-long commitment even when the price is advertised as monthly.",
      "stance": "risk",
      "quote": "Adobe transitioned to a subscription model in 2012, requiring users to pay regularly for access to its software, including popular products like Photoshop and Acrobat[[3]](#cite-adobe-3)"
    },
    {
      "ref": "[3]",
      "area": "money",
      "claim": "A parent reports that Adobe's website explains its subscription terms and refund policy.",
      "stance": "mitigation",
      "quote": "Adobe's own page explains its subscription terms and refund policy[[3]](#cite-adobe-3)"
    },
    {
      "ref": "[4]",
      "area": "neutral",
      "claim": "A parent reports that Adobe's General Counsel stated the company is transparent and has a simple cancellation process, and will refute FTC's claims in court.",
      "stance": "neutral",
      "quote": "We are transparent with the terms and conditions of our subscription agreements and have a simple cancellation process. We will refute FTC's claims in court[[4]](#cite-adobe-4)"
    },
    {
      "ref": "[6]",
      "area": "neutral",
      "claim": "A parent reports that Adobe dropped its Figma acquisition bid due to regulatory opposition and paid a $1 billion breakup fee.",
      "stance": "neutral",
      "quote": "Adobe drops the Figma bid citing regulatory opposition and pays a $1 billion breakup fee[[6]](#cite-variety-6)"
    },
    {
      "ref": "[6]",
      "area": "neutral",
      "claim": "A parent reports that Adobe's attempt to acquire Figma for $20 billion faced antitrust scrutiny.",
      "stance": "neutral",
      "quote": "Adobe's recent attempt to acquire the product design platform Figma for $20 billion[[5]](#cite-the-verge-5) faced antitrust scrutiny, reflecting continued regulatory challenges for the company[[6]](#cite-variety-6)"
    }
  ]
}
